import { useState } from 'react';
import { User, Lock, ArrowRight, Eye, EyeOff } from 'lucide-react';
import AppLogo from './components/assets/logo.png';

const BASE = 'http://localhost:8080';

async function api(path, method = 'GET', body = null) {
  try {
    const opts = { method, headers: {} };
    if (body) { opts.headers['Content-Type'] = 'application/json'; opts.body = JSON.stringify(body); }
    const r = await fetch(BASE + path, opts);
    return r.json();
  } catch {
    return { success: false, error: 'Cannot connect to server.' };
  }
}

const GREEN = '#2d5a1b';

function Auth({ onSuccess, notify }) {
  const [form, setForm]           = useState({ username: '', password: '' });
  const [loading, setLoading]     = useState(false);
  const [errors, setErrors]       = useState({});
  const [focused, setFocused]     = useState('');
  const [showPass, setShowPass]   = useState(false);
  const [showForgot, setShowForgot] = useState(false);

  const validate = () => {
    const e = {};
    if (form.username.length < 3) e.username = 'Username must be at least 3 characters';
    if (form.password.length < 6) e.password = 'Password must be at least 6 characters';
    setErrors(e);
    return Object.keys(e).length === 0;
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!validate()) return;
    setLoading(true);
    const r = await api('/api/login', 'POST', { username: form.username, password: form.password, role: 'admin' });
    setLoading(false);
    if (r.success && r.role === 'admin') {
      onSuccess(r);
    } else if (r.role === 'driver' || r.role === 'passenger') {
      notify('Access denied. Admins only.', 'login-error');
    } else {
      notify(r.error || 'Invalid credentials. Please try again.', 'login-error');
    }
  };

  return (
    <div style={{
      minHeight: '100vh',
      background: 'linear-gradient(180deg, #e6cc00 0%, #fff59d 50%, #ffffff 100%)',
      display: 'flex', flexDirection: 'column',
      justifyContent: 'center', alignItems: 'center',
      padding: '60px 24px 40px',
      fontFamily: "'Segoe UI', sans-serif",
      position: 'relative', overflow: 'hidden',
    }}>

      {/* Background blobs */}
      <div style={{ position: 'absolute', top: '-140px', right: '-140px', width: '420px', height: '420px', borderRadius: '50%', background: 'rgba(255,255,255,0.18)', pointerEvents: 'none' }} />
      <div style={{ position: 'absolute', bottom: '-120px', left: '-120px', width: '380px', height: '380px', borderRadius: '50%', background: 'rgba(245,230,66,0.12)', pointerEvents: 'none' }} />

      {/* Logo */}
      <div style={{ width: '96px', height: '96px', borderRadius: '50%', background: 'rgba(255,255,220,0.55)', display: 'flex', alignItems: 'center', justifyContent: 'center', zIndex: 2, marginBottom: '-48px', boxShadow: '0 4px 20px rgba(0,0,0,0.10)' }}>
        <div style={{ 
          width: '72px', 
          height: '72px', 
          borderRadius: '50%', 
          background: '#e6cc00', 
          display: 'flex',
          alignItems: 'center', 
          justifyContent: 'center', 
          boxShadow: '0 4px 14px rgba(0,0,0,0.1)',
          overflow: 'hidden'
        }}>
          <img src={AppLogo} alt="Logo" style={{ width: '100%', height: '100%', objectFit: 'cover' }} />
        </div>
      </div>

      {/* White Card */}
      <div style={{ background: '#ffffff', borderRadius: '28px', boxShadow: '0 20px 60px rgba(0,0,0,0.10), 0 4px 16px rgba(0,0,0,0.06)', maxWidth: '440px', width: '100%', padding: '68px 36px 36px', position: 'relative', zIndex: 1 }}>

        {/* Title */}
        <div style={{ textAlign: 'center', marginBottom: '28px' }}>
          <h1 style={{ fontSize: '1.9rem', fontWeight: '800', color: GREEN, margin: '0 0 6px', letterSpacing: '-0.3px' }}>eTODA Nagcarlan</h1>
          <p style={{ fontSize: '0.92rem', color: 'rgba(0,0,0,0.54)', margin: 0 }}>Login to your admin account</p>
        </div>

        <form onSubmit={handleSubmit}>

          {/* Username */}
          <div style={{ marginBottom: '14px' }}>
            <div style={{ position: 'relative', borderRadius: '15px', background: '#ffffff', border: `2px solid ${focused === 'username' ? GREEN : errors.username ? '#ef4444' : '#e8eddf'}`, boxShadow: '0 2px 8px rgba(0,0,0,0.05)', transition: 'border 0.2s' }}>
              <User size={17} style={{ position: 'absolute', left: '14px', top: '50%', transform: 'translateY(-50%)', color: focused === 'username' ? GREEN : '#9ca3af', transition: 'color 0.2s' }} />
              <input
                type="text" placeholder="Username"
                value={form.username}
                onChange={e => setForm(p => ({ ...p, username: e.target.value }))}
                onFocus={() => setFocused('username')}
                onBlur={() => setFocused('')}
                style={{ width: '100%', padding: '15px 14px 15px 44px', border: 'none', borderRadius: '15px', fontSize: '1rem', background: 'transparent', outline: 'none', boxSizing: 'border-box', color: '#1a1a1a' }}
              />
            </div>
            {errors.username && <div style={{ color: '#ef4444', fontSize: '0.78rem', marginTop: '4px', paddingLeft: '2px' }}>{errors.username}</div>}
          </div>

          {/* Password with show/hide toggle */}
          <div style={{ marginBottom: '10px' }}>
            <div style={{ position: 'relative', borderRadius: '15px', background: '#ffffff', border: `2px solid ${focused === 'password' ? GREEN : errors.password ? '#ef4444' : '#e8eddf'}`, boxShadow: '0 2px 8px rgba(0,0,0,0.05)', transition: 'border 0.2s' }}>
              <Lock size={17} style={{ position: 'absolute', left: '14px', top: '50%', transform: 'translateY(-50%)', color: focused === 'password' ? GREEN : '#9ca3af', transition: 'color 0.2s' }} />
              <input
                type={showPass ? 'text' : 'password'}
                placeholder="Password"
                value={form.password}
                onChange={e => setForm(p => ({ ...p, password: e.target.value }))}
                onFocus={() => setFocused('password')}
                onBlur={() => setFocused('')}
                style={{ width: '100%', padding: '15px 44px 15px 44px', border: 'none', borderRadius: '15px', fontSize: '1rem', background: 'transparent', outline: 'none', boxSizing: 'border-box', color: '#1a1a1a' }}
              />
              {/* Show/Hide toggle button */}
              <button
                type="button"
                onClick={() => setShowPass(!showPass)}
                style={{ position: 'absolute', right: '12px', top: '50%', transform: 'translateY(-50%)', background: 'none', border: 'none', cursor: 'pointer', padding: '4px', color: '#9ca3af', display: 'flex', alignItems: 'center' }}
              >
                {showPass ? <EyeOff size={17} /> : <Eye size={17} />}
              </button>
            </div>
            {errors.password && <div style={{ color: '#ef4444', fontSize: '0.78rem', marginTop: '4px', paddingLeft: '2px' }}>{errors.password}</div>}
          </div>

          {/* Forgot Password */}
          <div style={{ textAlign: 'right', marginBottom: '22px' }}>
            <button
              type="button"
              onClick={() => setShowForgot(true)}
              style={{ background: 'none', border: 'none', cursor: 'pointer', color: GREEN, fontSize: '0.88rem', fontWeight: '700', padding: 0 }}
            >
              Forgot Password?
            </button>
          </div>

          {/* Login Button */}
          <button
            type="submit" disabled={loading}
            style={{ width: '100%', padding: '15px', background: loading ? '#4a7c5f' : GREEN, color: '#fff', border: 'none', borderRadius: '15px', fontSize: '1rem', fontWeight: '800', cursor: loading ? 'not-allowed' : 'pointer', letterSpacing: '1.5px', display: 'flex', alignItems: 'center', justifyContent: 'center', gap: '8px', boxShadow: '0 4px 18px rgba(45,90,27,0.3)', transition: 'opacity 0.2s', opacity: loading ? 0.75 : 1 }}
            onMouseEnter={e => { if (!loading) e.currentTarget.style.opacity = '0.88'; }}
            onMouseLeave={e => { e.currentTarget.style.opacity = '1'; }}
          >
            {loading ? 'Please wait...' : (<>LOGIN <ArrowRight size={16} /></>)}
          </button>

          {/* Divider */}
          <div style={{ display: 'flex', alignItems: 'center', margin: '20px 0', gap: '10px' }}>
            <div style={{ flex: 1, height: '1px', background: 'rgba(0,0,0,0.12)' }} />
            <span style={{ fontSize: '0.75rem', color: '#9aaa7a', fontWeight: '600', letterSpacing: '0.5px' }}>ADMIN PORTAL</span>
            <div style={{ flex: 1, height: '1px', background: 'rgba(0,0,0,0.12)' }} />
          </div>

          {/* Authorized badge */}
          <div style={{ textAlign: 'center', padding: '13px', border: `1.5px solid ${GREEN}`, borderRadius: '15px', color: GREEN, fontSize: '0.82rem', fontWeight: '700', letterSpacing: '0.5px', background: 'transparent' }}>
            🔒 AUTHORIZED PERSONNEL ONLY
          </div>

        </form>
      </div>

      {/* Footer */}
      <div style={{ marginTop: '24px', fontSize: '11px', color: 'rgba(45,90,27,0.5)', textAlign: 'center', letterSpacing: '0.3px' }}>
        eTODA Nagcarlan · LGU Admin System
      </div>

      {/* ── Forgot Password Modal ── */}
      {showForgot && (
        <div style={{ position: 'fixed', inset: 0, background: 'rgba(0,0,0,0.5)', display: 'flex', alignItems: 'center', justifyContent: 'center', zIndex: 9999, padding: '24px' }}>
          <div style={{ background: '#fff', borderRadius: '24px', padding: '36px 32px', maxWidth: '400px', width: '100%', boxShadow: '0 20px 60px rgba(0,0,0,0.2)' }}>
            <h2 style={{ fontSize: '1.3rem', fontWeight: '800', color: GREEN, margin: '0 0 8px' }}>Forgot Password?</h2>
            <p style={{ fontSize: '0.88rem', color: '#6b7280', margin: '0 0 24px' }}>
              Please contact your system administrator to reset your admin password.
            </p>
            <div style={{ background: '#f0fdf4', border: `1.5px solid ${GREEN}`, borderRadius: '12px', padding: '14px 16px', marginBottom: '24px' }}>
              <div style={{ fontSize: '0.82rem', color: GREEN, fontWeight: '700', marginBottom: '4px' }}>📞 Contact Admin Office</div>
              <div style={{ fontSize: '0.8rem', color: '#374151' }}>eTODA Nagcarlan LGU Admin Office</div>
              <div style={{ fontSize: '0.8rem', color: '#374151' }}>Nagcarlan, Laguna</div>
            </div>
            <button
              onClick={() => setShowForgot(false)}
              style={{ width: '100%', padding: '13px', background: GREEN, color: '#fff', border: 'none', borderRadius: '12px', fontSize: '0.95rem', fontWeight: '700', cursor: 'pointer', letterSpacing: '0.5px' }}
            >
              Got it
            </button>
          </div>
        </div>
      )}

    </div>
  );
}

export default Auth;